-- Generated by scripts/feature-post.mjs. Makes "holiday-email-holdout-group" the featured Industry LoogoBlog
-- post. Clear first, then set, so posts_one_featured never sees two rows.
UPDATE "posts" SET "featured" = false WHERE "featured" AND "slug" <> 'holiday-email-holdout-group';
UPDATE "posts" SET "featured" = true WHERE "slug" = 'holiday-email-holdout-group' AND "status" = 'published';
